// Builds upstream.patch from a site: everything we changed in upstream's files, against
// the upstream commit the site is built on. Reads the site's git state, never writes it.
import {execFileSync, spawnSync} from "node:child_process";
import {ASSETS} from "./paths.mjs";

// Generated by the build, local-only, or living in this repo instead.
const EXCLUDE = [
	// Every page is generated, including the SEO ones under bestiary/, items/ and spells/.
	":(exclude,glob)**/*.html",
	":(exclude)css",
	":(exclude)search",
	":(exclude)sw.js",
	":(exclude)sw-injector.js",
	":(exclude)homebrew",
	":(exclude)shell",
	...ASSETS.map(rel => `:(exclude)${rel}`),
];
// New files only count under the source folders; anything else untracked is local clutter.
const NEW_FILE_DIRS = ["js", "node", "scss"];

const git = (site, ...args) => execFileSync("git", ["-c", "core.quotePath=false", ...args], {cwd: site, encoding: "utf8", maxBuffer: 256 * 1024 * 1024});

export const findBase = site => {
	const commit = git(site, "merge-base", "HEAD", "upstream/main").trim();
	const describe = git(site, "describe", "--tags", "--always", commit).trim();
	return {commit, describe};
};

// --no-index exits 1 when the files differ, which is the expected case here.
const newFileDiff = (site, rel) => {
	const out = spawnSync("git", ["diff", "--no-index", "--binary", "--", "/dev/null", rel], {cwd: site, encoding: "utf8", maxBuffer: 64 * 1024 * 1024});
	if (out.status !== 1) throw new Error(`git diff --no-index ${rel}: ${out.stderr.trim()}`);
	return out.stdout;
};

export const buildPatch = (site, base, {dirs = ["."], committedOnly = false} = {}) => {
	const range = committedOnly ? `${base}..HEAD` : base;
	const tracked = git(site, "diff", "--binary", range, "--", ...dirs, ...EXCLUDE);
	if (committedOnly) return tracked;
	const newDirs = dirs.length === 1 && dirs[0] === "."
		? NEW_FILE_DIRS
		: dirs.filter(d => NEW_FILE_DIRS.includes(d));
	const untracked = newDirs.length
		? git(site, "ls-files", "--others", "--exclude-standard", "-z", "--", ...newDirs, ...EXCLUDE)
			.split("\0")
			.filter(Boolean)
			.sort()
		: [];
	return tracked + untracked.map(rel => newFileDiff(site, rel)).join("");
};

export const patchFiles = patch => [...patch.matchAll(/^diff --git a\/(\S+) b\/\S+$/gm)].map(m => m[1]);

// Keeps only file diffs under the given top-level directories (e.g. ["js", "node", "scss"]).
export const filterPatchByDirs = (patch, dirs) => {
	const prefixes = dirs.map(d => `${d.replace(/\/+$/, "")}/`);
	const normalized = patch.replace(/\r\n/g, "\n");
	const chunks = normalized.split(/(?=^diff --git )/m);
	return chunks
		.filter(chunk => {
			const m = /^diff --git a\/(\S+) b\/\S+/m.exec(chunk);
			return m && prefixes.some(p => m[1].startsWith(p));
		})
		.join("");
};

// The header line git apply ignores, naming what the patch was built on.
export const patchHeader = ({describe, commit}) => `HBM edits to homebrew-tools-src, built on upstream ${describe} (${commit})\n`;
